import json
import re
from datetime import date

_DAY_FORMAT = re.compile(r'\d{4}-\d{2}-\d{2}')


def _validate_day(value):
    """Return value if it is a valid YYYY-MM-DD calendar date; else ValueError."""
    if not isinstance(value, str) or not _DAY_FORMAT.fullmatch(value):
        raise ValueError(f'day must be a YYYY-MM-DD string, got {value!r}')
    try:
        date.fromisoformat(value)
    except ValueError:
        raise ValueError(f'day is not a valid calendar date: {value!r}') from None
    return value


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    rows = json.loads(text)  # json.JSONDecodeError is a ValueError subclass
    if not isinstance(rows, list):
        raise ValueError(f'expected a JSON array of rows, got {type(rows).__name__}')

    row_count = 0
    total_cents = 0
    first_day = None
    last_day = None

    for row in rows:
        if not isinstance(row, dict):
            raise ValueError(f'row must be a JSON object, got {row!r}')

        tenant = row.get('tenant')
        if not isinstance(tenant, str) or not tenant:
            raise ValueError(f'tenant must be a nonempty string, got {tenant!r}')

        amount = row.get('amount_cents')
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError(f'amount_cents must be an integer, got {amount!r}')

        day = _validate_day(row.get('day'))

        row_count += 1
        total_cents += amount
        if first_day is None or day < first_day:
            first_day = day
        if last_day is None or day > last_day:
            last_day = day

    return {
        'row_count': row_count,
        'total_cents': total_cents,
        'first_day': first_day,
        'last_day': last_day,
    }
"}

